# PatientRecord: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Patientrecord:
    patient_id: str = None  # MRN hash
    birth_year: float = None  # Year
    sex: str = None  # M/F/X
    language: str = None  # Preferred
    active: bool = None  # Active?

REQUIRED = ["patient_id", "birth_year", "sex", "language"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'patient_id': 'PT-9F2A', 'birth_year': 1978, 'sex': 'F', 'language': 'en', 'active': True}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

